export function selectWindow(events, count) {
	if (count <= 0) return [];
	return events.slice(0, count);
}

import assert from "node:assert/strict";
import { selectWindow } from "./src/window.mjs";
const events = ["a", "b", "c", "d"];
assert.deepEqual(selectWindow(events, 2), ["c", "d"]);
assert.deepEqual(selectWindow(events, 20), events);
assert.deepEqual(selectWindow(events, 0), []);
assert.deepEqual(selectWindow(events, -3), []);
console.log("window verifier passed");

